SELECT '4-Team Double Elimination', 'Standard 4-team double elimination: winners bracket, losers bracket, grand final with an if-necessary reset game.', '{"numTeams":4,"rounds":[{"round":0,"games":[{"id":"g1","seeds":[1,4],"group":"winners","col":0,"row":0,"label":"WB R1"},{"id":"g2","seeds":[2,3],"group":"winners","col":0,"row":1,"label":"WB R1"}]},{"round":1,"games":[{"id":"g3","feeds":[{"from":"g1","outcome":"winner"},{"from":"g2","outcome":"winner"}],"group":"winners","col":1,"label":"WB Final","row":0.5},{"id":"g4","feeds":[{"from":"g1","outcome":"loser"},{"from":"g2","outcome":"loser"}],"group":"losers","col":1,"label":"LB R1","row":3}]},{"round":2,"games":[{"id":"g5","feeds":[{"from":"g3","outcome":"loser"},{"from":"g4","outcome":"winner"}],"group":"losers","col":2,"label":"LB Final","row":3}]},{"round":3,"games":[{"id":"g6","feeds":[{"from":"g3","outcome":"winner"},{"from":"g5","outcome":"winner"}],"group":"final","col":3,"label":"Grand Final","row":1.75}]},{"round":4,"games":[{"id":"g7","feeds":[{"from":"g6","outcome":"winner"},{"from":"g6","outcome":"loser"}],"group":"final","col":4,"ifNecessary":true,"label":"Grand Final (if necessary)","row":1.75}]}],"bracketType":"double_elimination"}'::jsonb, true, NULL, 'double_elimination', 4
WHERE NOT EXISTS (
  SELECT 1 FROM public.bracket_templates WHERE name = '4-Team Double Elimination' AND created_by IS NULL
);

